  <svg ref={props.ref} data-component="logo-splash" class={props.class} viewBox="0 0 64 64" aria-label="MediaFlow"><Shape /></svg>
)

export const Logo = (props: { class?: string }) => (
  <svg data-component="logo" class={props.class} viewBox="0 0 270 64" aria-label="MediaFlow">
